INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','دليل عملي للمزارعين العراقيين حول استراتيجيات الوقاية والعلاج المتكاملة للآفات وأمراض القرع عند استخدام أنظمة الري بالتنقيط وشريط تي (تريب) لتحسين المكافحة والحد من انتشار الأمراض.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
