INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2> Муқаррарот: Корбандӣ номиқайиб байни обёрӣ ва саломати гиёҳот </h2>\n<p>Дар кишоварзии муосир, робитаи байни идоракунии обёрӣ ва назорати зараррасонҳо ва бемориҳо сиҳор ва ҷадугӣ нест, балки як ҳақиқати физиологии мустаҳкам аст. Бисёр кишоварзон ба ин боварӣ доранд, ки обёрӣи қатрагӣ танҳо усули сарфнамии об аст, аммо ин тасаввур хато аст. Яке система <strong>обёрӣи қатрагӣ</strong> ё <strong>нуворишҳои наварӣ</strong> ки бо дурустӣ тарҳрезӣ ва амалӣ шуда бошад, бевосита ба патологияи гиёҳи кабӯста таъсир мерасонад. Бо кам шудани намии сатҳӣ ва пешгирии намшавии нодурусти дастонаҳо ва баргҳои поёнӣ, мо амалан заминаи рӯиши занбӯруғҳои тӯлбӯлакӣ ва бемориҳои бактериявиро нобуд мекунем.</p>\n<p>Кабӯста, ба ҳайси гиёҳи бо инкишофи тез ва пӯшиши дӯдона, дар сурати нам будани доимии хок, бо тезӣ ба вайроншавии реша мебошад. Дар тарафи дигар, зараррасонҳои ҳашаротӣ чунин <strong>шиштҳои сафед</strong> ва <strong>микоплазмаи кادӯ</strong> ки интиқолдиҳандаи вирусҳои вирусӣ мебошанд, дар ҳавои тар ва бо афзоиши ғайриоддии лӯбиҳо, зичии баландтаре доранд. Ҳадафи ин мақола пешниҳоди як қад-қади амалиётӣ барои ҳамбастасозии идоракунии зараррасонҳо бо доираҳои обёрӣ кардани кадӯ мебошад.</p>\n\n<>\n\n<h2> Механизмҳои муҳофизатии обёрӣ кардани маҳаллӣ бар зиддияти беморӣ </h2>\n<h3> Кам кардани бӯрои рушди қарчҳо тавассути назорати намакнокӣ ва таррӯӣ </h3>\n<p>Бемориҳои қарчӣ дар кадӯ, ба монанди ботритис (Botrytis) ва пӯсиши нарм, ба таррӯии нисбии баланд ва тамоси бечори барг бо замин вобастаанд. Дар системаҳои анъанавии обёрӣ кардан ба монанди обтозонӣ ё пухонидан, таррӯӣ дар тамоми ҳудуди решагӣ ва инчунин дар сатҳи замин нигоҳ дошта мешавад. Аммо дар системаи нигоҳдории идоракунии равиши обёрӣ кардан, мо танҳо ҳудуди решагии муҳимро (Root Zone) хнам мекунем. Ин кор боиси мешавад, ки сатҳи замин нисбатан хушк бомадонад ва доираи хушк-хнам (Dry-Wet Cycle) тезтар ба вуҷуд ояд. Ин доира барои қарчҳо зараррасон аст, зеро онҳо барои пайдоиш ва спорулятсия ба таррӯии доимӣ ниёз доранд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-کدو-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="آفات و بیماری‌های کدو با آبیاری قطره‌ای - تصویر 1"/><figcaption>crop pests diseases drip irrigation кадӯ</figcaption></figure>\n<h3> Пешгирии бемориҳои решагӣ тавассути танзими EC </h3>\n<p>Дуҳом ва будокҳои химӣ метавонад тавассути ҳамон қутраҳо ба реша бирисанд, аммо таваҷҷуҳи асосии мо ба физикаи об аст. Рақобати зиёд боиси коҳиши оксигени замин ва осиб ба бофтаи реша мегардад, ки дар натиҷа набатро ба бемориҳои бактериявӣ (ба мисли пизитиум) ҳосилманд мекунад. Дар обёрӣи қутравӣ бо танзими дақиқ даромад ва вақти обёрӣ мо метавонем зонаи оксигенро нигоҳ дорем. Фаромӯш накунед, ки саломати реша мустақиман ба қобилияти набат дар пешгирӣи моддаҳои заҳирҳои зараранҷорон ва ҷабби моддаҳои ғизоӣ вобаста аст.</p>\n\n<>\n\n<h2> Идоракунии шитумии ҳашарот ва вирусҳо тавассути обёрӣи қутравӣ </h2>\n<h3> Нақши рақобат дар давраи ҳаёти шашакҳои сафед </h3>\n<p>Шашаки сафеди каду яке аз пуршумораин зараранҷорон ин маҳсулот аст. Ин ҳашарот дар шароити гарм ва намнок бо суръати бозӣ таъом хӯрдан ва насл бардоштанро зиёд мекунанд. Рақобати баланд боиси истеҳсоли бештари асал (Honeydew) тавассути шашакҳо мегардад, ки заминаи рушди чарокии зангор (Sooty Mold) мебошад. Ин зангор нурро барои раъйшакунӣ маҳдуд мекунад ва набатро заиф мекунад. Бо назорати дақиқ нӯри обёрӣ (Emitters) ва пешгирӣ аз паҳкши обҳои иловагӣ бар баргҳо, мо рақобати нисбии маҳаллӣ-ро кам мекунем. Инчунин, шустан бо об метавонад ҳамчун воситаи кӯмакӣ (не асосӣ) барои отаи қисме аз шашакҳои сатҳи барг хизмат кунад, аммо бояд ҳамчун назорати биологӣи якпора шинос нашуда шавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-کدو-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="آفات و بیماری‌های کدو با آبیاری قطره‌ای - تصویر 2"/><figcaption>zararbar konandagon bemoiri obori chutaq kado</figcaption></figure>\n<h3> Назорати векторҳои вирусӣ тавассути коҳиши стресси набат </h3>\n<p>Паштҳои баргхӯр (Leafhoppers) интиқолдиҳандаи вирусҳои мусайкака кукуруз мебошанд. Вақте набат зери стресси гидроклиқӣ қарор дорад (кам об ё зиёд об), муқовимати химиявии набат паст мешавад ва вирус дар бофтаҳо тезтар зиёд мегардад. Обёрӣи қутравӣ бо дақиқии миллиметр-соатӣ ба нигоҳ доштани мувозинати оби реша кӯмак мекунад ва набатро дар баландии қобилияти рушд нигоҳ медорад. Набатҳои қавӣ бофтаҳои ғовузиштар доранд, ки вориди вирусро душвор мекунад. Дар ин соҳа, фаҳмиши <a href="https://navar-abyari.ir/optimal-wall-thickness-tip-irrigation-tape/">Ҳаҷми коҳишдиҳандаи зарфи ларзи обкорӣ</a> Барои пешгирии рақобат ва нигоҳ доштани фишори якхела дар тамоми қуттҳо хеле муҳим аст; зеро рақобат боиси партофани намӣ ба таври беҳудуд мешавад ва нуқтаҳои устувори намдорро дар замин эҷод мекунад, ки муҳити муносиб барои қашқашҳои заминӣ мебошанд.</p>\n\n<>\n\n<h2> Омилҳои амалӣ барои кишоварон: аз тарроҳӣ то иҷро </h2>\n<ul>\n<li><strong>Дурузии сачандҳо:</strong> Барои каду, бо назардошти таваққуфи бодии наботот дар марҳилаҳои оянда, дурузии сачандҳо набояд аз 20 сантимертара аз гӯша камтар бошад, то ки зарари мустақим ба дарахти асосӣ ворид нашавад. Беҳтар аст, ки ду навиши теб аз ду ҷониби зарф иҷро карда шаванд.</li>\n<li><strong>Таваққуфи вақти обкорӣ:</strong> Обкориро дар соатҳои субҳи ором иҷро кунед. Ин кор боиси он мешавад, ки ҳарорати замин аз пайи бодазди (вақте ки шипшикҳо фаъолтарин мебошанд) хунук монанд ва намҳои шабона коҳиш меёбад. Аз обкории бозгоҳ бешубора кунед, ки боиси шабкорӣ ва афзоиши шитум мешавад.</li>\n<li><strong>Пешгирии заҳршавии решаҳо:</strong> Камин аз як бор дар сол филтрҳои асосӣ ва маҳаллии системаро санҷида, тоза кунед. Истисори навои борик пайдашавии нуқтаҳои хушк дар маркази реша ва таррашави дар атрофро ба вуҷуд меорад, ки ба вазъи рушди реша ихтилос мекунад.</li>\n<li><strong>Истиноди маводи органикӣ:</strong> Дархордани маводи органикӣ ба хок тавассути хатҳои қатраӣ (Soil Injection) метавонад бо таъмини мувозинати микробиологӣ аз хок, фаъолияти қашқумҳои боиси бемориро кам кунад.</li>\n<li><strong>Назорати бинӣ:</strong> Ба ҷои таян кардан ба тақвими дарахтҳо, ба ҳарорати баргҳо (бо thermometer мулоқоти дарозмавҷ) ва ранги баргҳо диққат диҳед. Тағйирёбии ранги зарҳалпайин (Chlorosis) метавонад ишораи заҳм шудан ба ҳашари талмандор бошад, на ҳатман камбудии оҳан.</li>\n</ul>\n\n<h2> Саволҳои мулоим (FAQ) дар бораи идоракунии ҳашарот бо қатраӣ </h2>\n<ol>\n<li><strong>Оё имкон дорад доруҳои ҳашаркушро тавассути қатраҳо истифода барем?</strong>\n<br>Не, тақрибан ҳамаи доруҳои ҳашаркушҳои хушк аз сабаби зарраҳои мулоим, нави қатраиқро баст мекунанд. Танҳо моддаҳои химиявии махсус ва гушуде, ки барои обёрёнии химиявӣ (Fertigation) тарҳрезӣ шудаанд, иҷозат доранд. Барои идоракунии хӯшаҳо аз спрей кардани сатҳӣ истифода баред.</li>\n<li><strong>Оё обори қатқалӣ (дворобӣ) боиси зиёд шудани ҳашароти шубашт аст?</strong>\n<br>Не, дар сурати он ки об мустақиман ба баргҳо пароканда нашавад (мисли парокунӣ бо шӯрӯб). Лавҳаҳои тиб ва қатқалҳодиҳандаҳои оддӣ танҳо хокро тар мекарданд. Шубаштҳо бештар дар шароити намноки ҳавои атрофи реша намоиш меёбанд, на бо таркунӣ. Пас назорати намнокии муҳит тавассути ҷойгир кардани сафҳо ва ҳавопазири муҳимтар аст.</li>\n<li><strong>Вақти беҳтарин барои шустани намнокии бактериявӣ кадом аст?</strong>\n<br>Ҳангоми муайян кардани бемории ибтидоии зангнолудкӣ ё хунук, як обори вазнин ва кӯтоҳ (Tozalī) метавонад кӯмакрасона бошад, аммо агар сарчашмаи сироят (ҳашароти зараррасон ё буғ) нест накунед, таъсир муваққатӣ аст. Аввал сарчашмаи сироятро хомӯш кунед.</li>\n<li><strong>Оё дар парвози дучоқ (Сафҳои дучоқ) лавҳа бояд кӯтоҳтар бошад?</strong>\n<br>Бале, дар парвози дучоқ, масофа байни қатқалҳодиҳандаҳо бояд барои решаи дучоқ мутобиқ шавад. Агар фазо байни тӯҷҳо кам бошад, лавҳаи иловагиро нест кунед ва ба зичии қатқалҳодиҳанда дар назди дарахти тарез кунед, то намнокӣ байни тӯҷҳо ҷамъ нашавад.</li>\n</ol>\n\n<h2> Хулоса ва ояндаи оянда </h2>\n<p>Ивазкунии идоракунии зараррасонҳо бо системҳои <strong>Обиёри пичкоӣ</strong> ва <strong>наварчаҳои тип</strong> як зарурат аст, на ягон интихоб. Бо фаҳмидани он ки чӣ тавр як қатра об метавонад бемориро ба вуҷуд орад, деҳқон аз як истиъмолкунандаи содаткунандаи об ба як муҳандиси муҳити зистии решаӣ табдил меёбад. Бо кам кардани тарӣи иловагӣ, идоракунии шаъомҳои шпакҳо ва мустаҳкам намудани муқовимати ҷуншӯзҳо тавассути хостии гидравликӣ, дар натиҷа маҳсулоти солимтар, бо сифати баландтар ва бо хароҷоти пасттар (хатари лозимияти ба мавҷудияти зараррасонҳои давомӣ) мегиред. Маслиҳати мо ин аст, ки ҳаргиз пеш аз харидани системаи обиёри бо як мутахассиси зараррасонҳо ва бемориҳо машварат кунед, то ки дарозии наварчаҳои тип бо ҷойгиршавии гамет ва иқлими минтақаи шумо мувофиқ бошад. Барои дониши бештар дар бораи идоракунии манбаъҳо ва ҳисобкунии дақиқ, ба дастурҳои ҳаҷми фурӯши жӯъси мексикӣ ва ҳисобкунии дақиқи монанд барои дигар дон ва маҳсулоти ғаллаҳои дигар муроҷиат кунед.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-کدو-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="آفات و بیماری‌های کدو با آبیاری قطره‌ای - تصویر 3"/><figcaption>crop pests diseases drip irrigation кудӯ</figcaption></figure>\n<p><strong>Мавзӯҳои алоқаманд:</strong> <a href="https://navar-abyari.ir/black-radish-yield-per-hectare-factors/">black radish yield per hectare factors</a>, <a href="https://navar-abyari.ir/%D9%85%D9%82%D8%AF%D8%A7%D8%B1-%D8%A8%D8%B0%D8%B1-%D8%A7%D8%B1%D8%B2%D9%86-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">D985D982D8AFD8A7D8B1 D8A8D8B0D8B1 D8A7D8B1D8B2D986 D8AFD8B1 D987DAA9D8AAD8A7D8B1</a>, <a href="https://navar-abyari.ir/%d9%85%d9%82%d8%af%d8%a7%d8%b1-%d8%a8%d8%b0%d8%b1-%d8%b4%d8%a7%d9%87%db%8c-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Миқдори бехи шоҳӣ дар як гектар: омилҳои таъсиргузор ва усулҳои беҳтарсозӣ</a></p>','Идора кардани зарароварҳо ва бемориҳои кабубо дар системҳои обёрӣи қатрагӣ ва натибӣ','Оборишачии қатрагонафакатан барои кам кардани истеъмоли об нест, балки чорбае қувватнок барои идоракунии ҳашаротҳо ва бемориҳои қулобӣ-мани-ягон аст. Дар ин мақола мо мухосиси омилиро баррасӣ мекунем, ки чӣ тавр идоракунии дурусти намнокӣ бо наворҳои нав ғаққати ҷиҳатҳоро дар зидди ҳашароти пӯлӯи кунорӣ ва таркибҳои қулобӣ зиёд мекунад.','publish','closed','closed','zararavaro-ham-bemorihoi-kabubo-obori-qiqtargi-natiabi',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
